const cfg = $('Set Config').first().json;
// The Drive node returns one item per Doc (or a single empty item when the
// folder has none, because "Always Output Data" is on).
const files = $('List Case Docs').all().map(i => i.json).filter(f => f && f.id);
if (!files.length) {
  throw new Error('No Google Docs found in the Upload folder (' + cfg.uploadFolderId + '). Check the folder ID and that the Google Drive credential on "List Case Docs" can open that folder.');
}
const articles = $('Get Existing Cases').first().json.articles || [];

// A case counts as done once ANY post in the Project Showcase blog (draft or
// published) carries its case-number tag, e.g. "CA009". Doc names vary
// ("CA009", "Copy of CA004-UP", "UP-CA014"), so only the CA number matters.
const done = new Set();
for (const a of articles) {
  for (const t of String(a.tags || '').split(',')) {
    const m = t.trim().match(/^CA0*(\d+)$/i);
    if (m) done.add('CA' + m[1].padStart(3, '0'));
  }
}

// Update mode: Set Config -> updateCase = "CA002" re-processes that one case and
// overwrites its existing post (same URL, visibility unchanged). Leave empty
// for normal runs.
const wanted = String(cfg.updateCase || '').trim().toUpperCase().replace(/^CA0*(\d+)$/, (m, n) => 'CA' + n.padStart(3, '0'));
if (wanted) {
  const doc = files.find(f => { const m = String(f.name || '').match(/CA[\s_-]*0*(\d+)/i); return m && 'CA' + m[1].padStart(3, '0') === wanted; });
  if (!doc) throw new Error('updateCase ' + wanted + ': no Doc with that case number in the Upload folder.');
  const post = articles.find(a => String(a.tags || '').split(',').some(t => t.trim().toUpperCase() === wanted));
  if (!post) throw new Error('updateCase ' + wanted + ': no existing post with tag ' + wanted + ' -- clear updateCase to create it normally.');
  return [{ json: { docId: doc.id, docName: doc.name, caseNo: wanted, articleId: post.id, remainingAfterThis: 0, skipped: [] } }];
}

const pending = [];
const skipped = [];
for (const f of files) {
  const m = String(f.name || '').match(/CA[\s_-]*0*(\d+)/i);
  if (!m) { skipped.push(f.name + ' (no CA number in the name)'); continue; }
  const caseNo = 'CA' + m[1].padStart(3, '0');
  if (done.has(caseNo)) continue;
  if (pending.some(p => p.caseNo === caseNo)) { skipped.push(f.name + ' (same CA number as another Doc)'); continue; }
  pending.push({ docId: f.id, docName: f.name, caseNo });
}
pending.sort((a, b) => a.caseNo.localeCompare(b.caseNo));

console.log(JSON.stringify({ alreadyDone: [...done], pending: pending.map(p => p.caseNo), skipped }));
// One case per execution keeps every run small and avoids nested loops.
// Nothing left to publish -> stop quietly.
if (!pending.length) return [];
return [{ json: { ...pending[0], remainingAfterThis: pending.length - 1, skipped } }];

const meta = $('Pick Next Case').first().json;
// Full document structure from the Google Docs API (documents.get). Reading
// the Doc this way has no size limit -- Drive's HTML/Word export refuses any
// Doc over 10 MB (exportSizeLimitExceeded), which photo-heavy cases exceed.
const doc = $json;
const tab = doc.tabs && doc.tabs[0] && doc.tabs[0].documentTab;
const content = (doc.body && doc.body.content) || (tab && tab.body && tab.body.content);
if (!Array.isArray(content)) {
  throw new Error(meta.caseNo + ': the Google Docs API did not return the document structure.');
}
const inlineObjects = doc.inlineObjects || (tab && tab.inlineObjects) || {};
const positionedObjects = doc.positionedObjects || (tab && tab.positionedObjects) || {};

// Photos are numbered in the order they appear in the Doc. contentUri is a
// temporary (about 30 min) public link to the original image, which Shopify
// downloads directly a minute or two later.
const images = [];
function addImage(obj, oid) {
  const props = obj && (obj.inlineObjectProperties || obj.positionedObjectProperties);
  const uri = props && props.embeddedObject && props.embeddedObject.imageProperties && props.embeddedObject.imageProperties.contentUri;
  if (!uri) return null;
  images.push({ n: images.length + 1, src: uri, oid: oid || '' });
  return '[[IMG_' + images.length + ']]';
}

// Text of one paragraph; bold runs become <strong> (not in headings).
function paraText(p, keepBold) {
  let out = '';
  const ph = [];
  for (const el of p.elements || []) {
    if (el.textRun) {
      const t = String(el.textRun.content || '').replace(/\n/g, '').replace(/\u000b/g, keepBold ? '\u0003' : ' ');
      const bold = keepBold && el.textRun.textStyle && el.textRun.textStyle.bold && t.trim();
      out += bold ? '\u0001' + t + '\u0002' : t;
    } else if (el.inlineObjectElement) {
      const x = addImage(inlineObjects[el.inlineObjectElement.inlineObjectId], el.inlineObjectElement.inlineObjectId);
      if (x) ph.push(x);
    }
  }
  for (const id of p.positionedObjectIds || []) {
    const x = addImage(positionedObjects[id], id);
    if (x) ph.push(x);
  }
  let s = out.replace(/[ \t ]+/g, ' ').replace(/ *\n */g, '\n').trim();
  s = s.replace(/\u0002(\s*)\u0001/g, '$1').replace(/\u0001\s*\u0002/g, '');
  s = s.replace(/\s*\u0003\s*/g, '<br>');
  s = keepBold ? s.replace(/\u0001/g, '<strong>').replace(/\u0002/g, '</strong>') : s.replace(/[\u0001\u0002]/g, '');
  return { text: s, ph };
}

const lines = [];
for (const se of content) {
  if (se.paragraph) {
    const p = se.paragraph;
    const st = (p.paragraphStyle && p.paragraphStyle.namedStyleType) || 'NORMAL_TEXT';
    const isTitle = st === 'TITLE' || st === 'SUBTITLE';
    // A "heading" that contains Shift+Enter line breaks is really a block of
    // lines (e.g. Material / Dimensions / Finish) -- keep it as a paragraph.
    const multiLine = (p.elements || []).some(el => el.textRun && /\u000b/.test(el.textRun.content || ''));
    const isHeading = isTitle || (/^HEADING_\d$/.test(st) && !multiLine);
    const { text, ph } = paraText(p, !isHeading);
    const label = isTitle ? 'TITLE' : isHeading ? 'H' + st.slice(-1) : (p.bullet ? 'LI' : 'P');
    if (text) lines.push('[' + label + '] ' + text);
    if (ph.length) lines.push('[IMAGES] ' + ph.join(' '));
  } else if (se.table) {
    const rows = [];
    for (const r of se.table.tableRows || []) {
      const cells = [];
      for (const c of r.tableCells || []) {
        const parts = [];
        const phs = [];
        for (const ce of c.content || []) {
          if (!ce.paragraph) continue;
          const x = paraText(ce.paragraph, true);
          if (x.text) parts.push(x.text.replace(/\n/g, ' '));
          phs.push(...x.ph);
        }
        cells.push((parts.join(' ') + ' ' + phs.join(' ')).trim());
      }
      if (cells.some(Boolean)) rows.push(cells.join(' | '));
    }
    if (rows.length) lines.push('[TABLE]\n' + rows.join('\n') + '\n[/TABLE]');
  }
}

// Normalize headings so every Doc gives the same structure:
// - the first text line is the case title (Docs use H1, H2 or a bold line);
// - the remaining heading levels are shifted so the top level used becomes
//   H2 (main sections) and anything deeper becomes H3 (sub-sections).
const firstText = lines.findIndex(l => !l.startsWith('[IMAGES]') && !l.startsWith('[TABLE]'));
if (firstText >= 0) lines[firstText] = lines[firstText].replace(/^\[(?:TITLE|H\d|P)\]/, '[TITLE]').replace(/<\/?strong>/g, '');
const levels = lines.map(l => (l.match(/^\[H(\d)\]/) || [])[1]).filter(Boolean).map(Number);
const top = levels.length ? Math.min(...levels) : 2;
for (let i = 0; i < lines.length; i++) {
  lines[i] = lines[i].replace(/^\[H(\d)\]/, (m, lv) => '[H' + Math.min(3, 2 + (Number(lv) - top)) + ']');
}

// Template label headings with no content of their own ("2. 首图" = hero image)
// are removed before translation; the photo under them stays in place.
for (let i = lines.length - 1; i >= 0; i--) {
  if (/^\[H\d\]\s*(?:\d+\s*[.)）、]\s*)?(?:首图|主图|封面图|hero image|main image|cover image)\s*$/i.test(lines[i])) lines.splice(i, 1);
}

if (!images.length) throw new Error(meta.caseNo + ': no images found in the Doc.');
if (!lines.length) throw new Error(meta.caseNo + ': no text found in the Doc.');

const sourceText = lines.join('\n');
const systemPrompt = "You are the editor for Marblebee, a company that designs and fabricates custom natural-stone (marble) products. You turn an internal project case document into a polished English web page for the company's \"Project Showcase\" section.\n\nThe document is given as tagged lines: [TITLE] and [H1]-[H6] headings, [P] paragraphs, [LI] list items, [TABLE]...[/TABLE] blocks (one row per line, cells separated by \" | \"), and [IMAGES] lines that contain image placeholders such as [[IMG_3]]. Bold text is marked with <strong>...</strong>. Parts are written in Chinese; some parts may already be in English.\n\nReturn a JSON object with exactly two keys: \"title\" and \"body_html\".\n\nRules:\n1. Translate all Chinese into natural, professional US English. Keep the meaning. Do not add facts, claims, prices, promises or contact details that are not in the document. Keep text that is already in English (fix only obvious typos). Keep measurements, units, weights, dates, stone/material names and quoted client words exactly.\n2. \"title\": the project's English title, taken from the document's main title or first heading (translate it if needed). No case number, no numbering, no surrounding quotes.\n3. \"body_html\": the complete case study below the title. Do not repeat the title.\n   - Allowed tags only: h2, h3, p, br, ul, ol, li, strong, em, blockquote, table, thead, tbody, tr, th, td. No h1, no classes, no inline styles, no links, no <img> tags.\n   - Follow the document's own sections and order. Use h2 for main sections (for example Project Overview, Client Requirements, Our Solution, Design & Production Process, Technical Details, Finished Project Gallery, Client Feedback, Planning a Similar Project?) and h3 for sub-sections.\n   - Heading levels are already normalized: output every [H2] as h2 and every [H3] as h3, never change a level. The [TITLE] line is the title only and must not appear in body_html.\n   - Keep every heading the document has, translated; never replace a heading with a generic one (for example keep a closing heading like \"Renovating an old fireplace?\" as it is in the document).\n   - Remove document-outline numbering in front of section headings and bold label lines (such as \"2. \", \"3. \", \"1\uff09\", \"\u2465 \"). Keep step numbering of solution sub-headings such as \"01\uff5c\", written as \"01 | \".\n   - Drop headings that are only template labels with no content of their own, such as \"Hero Image\" / \"\u9996\u56fe\"; keep their images exactly where they were.\n   - <br> inside a line is a deliberate line break in the document (for example a list of specifications such as Material / Dimensions / Finish): keep every <br> where it is.\n   - Join lines that were broken in the middle of a sentence into one paragraph. If a line is marked as a heading but is clearly an ordinary sentence, output it as a paragraph.\n   - Text inside <strong>...</strong> in the document is bold in the original: keep the corresponding translated words in <strong>. Do not add bold anywhere else, and never inside headings.\n   - Tables: output an HTML table with two columns. If the first row is a header such as \"\u9879\u76ee | \u4fe1\u606f\" or \"\u9879\u76ee | \u89c4\u683c\" (or \"Item | Details\"), output it as a header row (\"Item | Details\" or \"Item | Specification\"). If project information appears as a run of \"Label: value\" pairs in one paragraph, convert it into such a table.\n   - Image placeholders: every placeholder [[IMG_n]] in the document must appear exactly once in body_html, in the same position and order as in the document. Put each [IMAGES] line in its own <p>; placeholders from the same [IMAGES] line stay together in that one <p>, separated by spaces. Never invent, renumber, move or drop placeholders.\n   - If the document contains the same case twice (for example a Chinese version followed by an English version without images), output it only once: use the version that contains the image placeholders as the structure, and you may reuse wording from the existing English version.\n   - Remove notes meant for the editor or staff (for example upload notes, \"UP\", \"\u5f85\u8865\u5145\", reminders in brackets).\n4. Output valid JSON only.";
const userPrompt = 'Case number: ' + meta.caseNo + '\nNumber of image placeholders: ' + images.length + '\n\nDOCUMENT:\n' + sourceText;
return [{ json: { ...meta, imageCount: images.length, images, sourceText, systemPrompt, userPrompt } }];

// Never upload the same photo twice:
// 1) Updating a posted case: every photo still unchanged in the Doc (same Doc
//    image id) keeps its existing Shopify URL, however long ago it was uploaded.
//    The Doc-image-id -> URL map is saved on the post as the metafield
//    showcase.image_map, so editing the post in Shopify admin can't lose it.
//    (The data-doc-img attributes in the body are only a fallback.)
//    Only new or replaced photos upload.
// 2) Re-running after a failed run: photos that run already uploaded (alt
//    "CA### - Image n", last 3 days, not FAILED) are reused.
const parsed = $('Parse Doc').first().json;
const res = $json;
if (res.errors) throw new Error('Shopify files lookup error: ' + JSON.stringify(res.errors));

const byOid = {};
const art = (res.data && res.data.article) || {};
try { Object.assign(byOid, JSON.parse((art.metafield && art.metafield.value) || '{}')); } catch (e) {}
const body = String((res.data && res.data.article && res.data.article.body) || '');
for (const m of body.matchAll(/<img\b[^>]*>/gi)) {
  const tag = m[0];
  const oid = (tag.match(/data-doc-img="([^"]+)"/) || [])[1];
  const src = (tag.match(/\ssrc="([^"]+)"/) || [])[1];
  if (oid && src && !byOid[oid]) byOid[oid] = src.replace(/&amp;/g, '&');
}

const nodes = (res.data && res.data.files && res.data.files.nodes) || [];
const prefix = parsed.caseNo + ' - Image ';
const recent = {};
for (const f of nodes) {
  const alt = String(f.alt || '');
  if (!alt.startsWith(prefix) || f.fileStatus === 'FAILED') continue;
  const n = Number(alt.slice(prefix.length));
  if (n && !recent[n]) recent[n] = f.id;
}

const reuseUrls = {};
const reuseIds = [];
const toUpload = [];
for (const i of parsed.images) {
  if (i.oid && byOid[i.oid]) reuseUrls[i.n] = byOid[i.oid];
  else if (recent[i.n]) reuseIds.push(recent[i.n]);
  else toUpload.push(i);
}
return [{ json: { reuseUrls, reuseIds, reusedCount: Object.keys(reuseUrls).length + reuseIds.length, toUpload, uploadCount: toUpload.length } }];

// Upload is skipped when every photo was already uploaded on an earlier run.
const created = $('Upload Images to Shopify').isExecuted ? $('Upload Images to Shopify').first().json : { data: { fileCreate: { files: [], userErrors: [] } } };
if (created.errors) throw new Error('Shopify fileCreate error: ' + JSON.stringify(created.errors));
const fc = created.data && created.data.fileCreate;
if (!fc) throw new Error('Unexpected fileCreate response: ' + JSON.stringify(created).slice(0, 500));
if (fc.userErrors && fc.userErrors.length) throw new Error('Shopify rejected some images: ' + JSON.stringify(fc.userErrors));

const expected = $('Parse Doc').first().json.imageCount;
const res = $json;
if (res.errors) throw new Error('Shopify file lookup error: ' + JSON.stringify(res.errors));
const nodes = (res.data && res.data.nodes) || [];
const urls = { ...($('Skip Already Uploaded').first().json.reuseUrls || {}) };
const failed = [];
let pending = 0;
for (const node of nodes) {
  if (!node) { pending++; continue; }
  const m = String(node.alt || '').match(/Image (\d+)$/);
  const n = m ? Number(m[1]) : null;
  if (node.fileStatus === 'FAILED') {
    failed.push((node.alt || node.id) + ': ' + JSON.stringify(node.fileErrors || []));
  } else if (node.fileStatus === 'READY' && node.image && node.image.url && n) {
    urls[n] = node.image.url;
  } else {
    pending++;
  }
}
if (failed.length) throw new Error('Shopify could not process these images: ' + failed.join(' ; ') + ' -- the Doc image links may not be publicly reachable.');

const attempt = $runIndex + 1;
if (pending || Object.keys(urls).length < expected) {
  if (attempt >= 12) throw new Error('Images still not ready after ' + attempt + ' checks (' + Object.keys(urls).length + '/' + expected + ').');
  return [{ json: { ready: false, attempt, ready_count: Object.keys(urls).length, expected } }];
}
return [{ json: { ready: true, urls, count: Object.keys(urls).length } }];

const meta = $('Parse Doc').first().json;
const cfg = $('Set Config').first().json;
const urls = $json.urls || {};
const raw = $('Translate & Structure (GPT)').first().json;
// The OpenAI node returns the first choice directly ({ message, finish_reason });
// the raw API shape ({ choices: [...] }) is accepted too.
const choice = (raw.choices && raw.choices[0]) || raw;
if (!choice || !choice.message) throw new Error(meta.caseNo + ': no response from OpenAI: ' + JSON.stringify(raw).slice(0, 500));
if (choice.finish_reason === 'length') throw new Error(meta.caseNo + ': the translation was cut off (max_tokens reached). Raise Maximum Number of Tokens in the OpenAI node.');
let out;
try {
  const c = choice.message && choice.message.content;
  out = typeof c === 'string' ? JSON.parse(c) : c;
} catch (e) {
  throw new Error(meta.caseNo + ': OpenAI did not return valid JSON.');
}
const title = String(out.title || '').trim();
let html = String(out.body_html || '').trim();
if (!title || !html) throw new Error(meta.caseNo + ': translation is missing the title or the body.');
// The page already shows the title -- drop it if the body repeats it as a heading.
const norm = s => String(s).replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim().toLowerCase();
html = html.replace(/^\s*<h[1-3][^>]*>([\s\S]*?)<\/h[1-3]>\s*/i, (m, inner) => norm(inner) === norm(title) ? '' : m);

// Template labels with no content of their own ("Hero Image" / 首图) are dropped;
// the photo under them stays where it is.
html = html.replace(/<h[23][^>]*>\s*(?:\d+[.)）]\s*)?(?:hero image|main image|cover image|featured image|首图|主图)\s*<\/h[23]>\s*/gi, '');
// Leftover outline numbering on bold label lines, e.g. "<strong>3) Factory finished product</strong>".
html = html.replace(/<p>\s*<strong>\s*\d+\s*[)）.]\s*/gi, '<p><strong>');
// Table labels (first column) are bold in the Docs -- keep that consistent
// whether or not the translation kept the <strong>.
html = html.replace(/<tr>(\s*)<td>(?!\s*<strong>)([\s\S]*?)<\/td>/gi, (m, sp, inner) => inner.trim() ? '<tr>' + sp + '<td><strong>' + inner.trim() + '</strong></td>' : m);

const esc = s => String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
const oidOf = {};
for (const i of meta.images || []) oidOf[i.n] = i.oid || '';
const img = n => '<img src="' + urls[n] + '"' + (oidOf[n] ? ' data-doc-img="' + esc(oidOf[n]) + '"' : '') + ' alt="' + esc(title) + ' - photo ' + n + '" loading="lazy" style="width:100%;height:auto;display:block;">';

const used = new Set();
// Photo 1 is also the post's featured image (shown at the top of the page).
// Skip it only when it would be the very first thing in the body -- the same
// photo stacked twice. When the Doc places it under text (e.g. after the
// Project Overview intro), keep it there, as the existing blog posts do.
html = html.replace(/^\s*<p>\s*\[\[IMG_1\]\]\s*<\/p>\s*/i, () => { used.add(1); return ''; });
// Photos keep the Doc's layout: each one full width, in the Doc's order
// (several photos in one Doc paragraph are still stacked full width there).
html = html.replace(/<p>\s*((?:\[\[IMG_\d+\]\]\s*)+)<\/p>/gi, (m, group) => {
  const ns = [...group.matchAll(/\[\[IMG_(\d+)\]\]/g)].map(x => Number(x[1])).filter(n => urls[n] && !used.has(n));
  ns.forEach(n => used.add(n));
  if (!ns.length) return '';
  return ns.map(n => '<p>' + img(n) + '</p>').join('');
});
// Any placeholder left inside other text.
html = html.replace(/\[\[IMG_(\d+)\]\]/g, (m, n) => {
  n = Number(n);
  if (!urls[n] || used.has(n)) return '';
  used.add(n);
  return img(n);
});

const warnings = [];
const missing = Object.keys(urls).map(Number).filter(n => !used.has(n)).sort((a, b) => a - b);
if (missing.length) {
  warnings.push('Photos the translation left out were added at the end: ' + missing.join(', '));
  html += missing.map(n => '<p>' + img(n) + '</p>').join('');
}
if (/[㐀-鿿]/.test(title + html)) warnings.push('Some Chinese text is still in the post -- check it before publishing.');

const publish = String(cfg.publish).toLowerCase() === 'true';
const article = {
  title,
  body_html: html,
  author: 'Marblebee',
  tags: meta.caseNo,
  template_suffix: cfg.templateSuffix,
  published: publish,
  image: { src: urls[1], alt: title }
};
const articleId = $('Pick Next Case').first().json.articleId || null;
// Updating keeps the post's current visibility.
if (articleId) delete article.published;
// Doc image id -> Shopify URL for every photo in this post; saved as a metafield.
const imageMap = {};
for (const i of meta.images || []) if (i.oid && urls[i.n]) imageMap[i.oid] = urls[i.n];
return [{ json: { article, articleId, imageMap, caseNo: meta.caseNo, docName: meta.docName, warnings } }];

const posted = $('Update Post').isExecuted ? $('Update Post').first().json : $('Create Post').first().json;
const a = posted.article || {};
const saved = (($json.data || {}).metafieldsSet || {});
const mapErrors = ($json.errors || saved.userErrors || []);
const b = $('Build Article').first().json;
const cfg = $('Set Config').first().json;
if (!a.id) throw new Error(b.caseNo + ': Shopify did not create the post: ' + JSON.stringify(posted).slice(0, 500));
return [{ json: {
  caseNo: b.caseNo,
  action: b.articleId ? 'updated' : 'created',
  doc: b.docName,
  title: a.title,
  published: !!a.published_at,
  adminUrl: 'https://admin.shopify.com/store/' + cfg.shop.replace('.myshopify.com', '') + '/content/articles/' + a.id,
  storeUrl: 'https://' + cfg.publicDomain + '/blogs/' + cfg.blogHandle + '/' + a.handle,
  warnings: b.warnings.concat(mapErrors.length ? ['Image map not saved (next update may re-upload photos): ' + JSON.stringify(mapErrors).slice(0, 300)] : []),
  photos: $('Parse Doc').first().json.imageCount,
  firstPublished: a.published_at || '',
  remainingCases: $('Pick Next Case').first().json.remainingAfterThis
} }];
